code.java:
class Solution {
    public int minElements(int[] nums,int limit,int goal){
        long sum=0;
        for(int value:nums)sum+=value;
        long difference=Math.abs((long)goal-sum);
        return (int)((difference+limit-1)/limit);
    }
}

code.kotlin:
class Solution {
    fun minElements(nums:IntArray,limit:Int,goal:Int):Int{
        val difference=kotlin.math.abs(goal.toLong()-nums.sumOf{
            it.toLong()
        });
        return ((difference+limit-1)/limit).toInt()
    }
}

code.cpp:
class Solution {
    public: int minElements(vector<int>& nums,int limit,int goal){
        long long sum=accumulate(nums.begin(),nums.end(),0LL),difference=llabs((long long)goal-sum);
        return (difference+limit-1)/limit;
    }
};
